import json,re,sys,pathlib,hashlib
root=pathlib.Path('/workspace/Paradigm');grid={p['id']:p for p in json.loads((root/'data/archetypes/grid.json').read_text())['people']}
protocol=(root/'docs/interview-protocol-v3.md').read_text()
cards={};card_names={}
for line in protocol.splitlines():
 m=re.match(r'\| (S[0-4]) \| ([^|]+) \| "(.*)" \|',line)
 if m: cards[m[1]]=m[3];card_names[m[1]]=m[2].strip()
qs=['If this happened, what would you say about it at work, to friends, or online?','And just between us, off the record, what do you really think it means for you?','What would you actually do, starting now and in the first year after it arrives? Be as specific as you can.','How does it feel, picturing that?']
normalize=lambda s: re.sub(r'\s+',' ',s.replace('’',"'").replace('“','"').replace('”','"')).strip()
for id in sys.argv[1:]:
 d=json.loads((root/'data/interviews/archetypes/raw'/f'{id}.json').read_text());p=grid[id];errs=[]
 for k in ['id','archetype','job','sector','name','levels']:
  if d[k]!=p[k]:errs.append(f'{k} profile mismatch')
 if d.get('countryContext')!='none':errs.append('countryContext')
 all_persona=[t['text'] for k in ['opening','closing'] for t in d[k] if t['speaker']=='persona']+[t['text'] for x in d['scenarios'].values() for t in x['transcript'] if t['speaker']=='persona']
 if not any(d['headlineQuote'] in t for t in all_persona):errs.append('headline quote not exact')
 for field in ['portrait','biggestWorry','whatWouldHelp']:
  for b in d[field]:
   if len(b.split())>22:errs.append(field+' bullet over22words')
   if sum(len(t.split()) for t in re.findall(r'\*\*([^*]+)\*\*',b))>4:errs.append(field+' bold over4words')
 for s,x in d['scenarios'].items():

  for st in x['steps']:
   if not 3<=len(st['text'].split())<=16:errs.append(s+' step actual wordcount '+str(len(st['text'].split())))
  if len(x['quote'].split())>30:errs.append(s+' quote over30words')
  if len(x['actions'])!=len(set(x['actions'])):errs.append(s+' duplicate action tags')
  ts=x['transcript'];it=[u['text'] for u in ts if u['speaker']=='interviewer'];pt=[u['text'] for u in ts if u['speaker']=='persona']
  if normalize(cards[s]) not in normalize(it[0]):errs.append(s+' exact card')
  if card_names[s] not in it[0]:errs.append(s+' missing scenario name')
  joined=' '.join(it);pos=[]
  for q in qs:
   if normalize(q) not in normalize(joined):errs.append(s+' missing question '+q)
   else:pos.append(normalize(joined).index(normalize(q)))
  if pos!=sorted(pos):errs.append(s+' question order')
  if len(it) not in [6,7] or len(pt)!=6:errs.append(s+f' question/answer counts {len(it)}/{len(pt)}')
  for i,t in enumerate(pt):
   n=len(re.findall(r'[.!?](?:[\s"\u201d]|$)',t))
   if n<2 or n>5:errs.append(s+f' answer {i} sentence count {n}')
  if not any(x['quote'] in t for t in pt):errs.append(s+' quote not exact')
  for k in ['say','think','do','feel','fieldNote']:
   for b in x[k]:
    if len(b.split())>22:errs.append(s+' '+k+' bullet over22words')
    if sum(len(t.split()) for t in re.findall(r'\*\*([^*]+)\*\*',b))>4:errs.append(s+' '+k+' bold over4words')
    if not re.search(r'\*\*[^*]+\*\*',b):errs.append(s+' '+k+' bullet without bold')
 print(id, 'PASS' if not errs else '\n  '+'\n  '.join(errs))

