"""Supplemental structure/literal audit. Does not claim semantic approval."""
import json,collections,re,sys
from pathlib import Path
root=Path('/tmp/paradigm-s7-20261118/insights/A29-206');stats=json.loads((root/'stats.json').read_text());rows=[json.loads(x) for x in (root/'sources.jsonl').read_text().splitlines()]
def words(s):return len(s.replace('**','').split())
for sc in sys.argv[1:]:
 d=json.loads((root/f'{sc}-draft.json').read_text());d=d.get(sc,d.get('scenarios',{}).get(sc,d));errors=[]
 def check(ok,msg):
  if not ok:errors.append(msg)
 for k in ['headline','whatTheyDo','whatTheySay','whatTheyThink','howTheyFeel','differences','quotes','thoughts','segments']:check(k in d,'missing '+k)
 for k in ['whatTheySay','whatTheyThink','howTheyFeel']:
  a=d.get(k,[]);check(2<=len(a)<=3,k+' count');check(any('**' in x for x in a),k+' bold')
  for x in a:check(words(x)<=24,k+' over24: '+x)
 acts=d.get('whatTheyDo',[]);check(3<=len(acts)<=5,'whatTheyDo count');check([x['tag'] for x in acts]==[x['tag'] for x in stats['scenarios'][sc]['actions'][:len(acts)]],'top action order')
 for x in acts:check(words(x['text'])<=24,'action prose over24: '+x['text'])
 check(2<=len(d.get('differences',[]))<=4,'differences count')
 for x in d.get('differences',[]):check(words(x['text'])<=24,'difference over24: '+x['text'])
 sources={r['id']:r for r in rows if r['scenario']==sc};quotes=d.get('quotes',[]);check(len(quotes)==3,'quote count');check(len({q['id'] for q in quotes})==3,'quote duplicates')
 for q in quotes:
  check(q['id'] in sources,'unknown quote source')
  if q['id'] in sources:
   r=sources[q['id']];check(q['name']==r['name'],'quote name');check(q['text']==r['quote'],'quote exact case/text')
 groups=d.get('thoughts',[]);check(3<=len(groups)<=6,'thought count');seen=collections.Counter()
 for g in groups:
  check(1<=words(g['text'])<=16,'thought heading words');check(len(set(g['ids']))==len(g['ids']),'duplicate group id');check(bool(g['ids']),'empty group')
  for i in g['ids']:check(i in sources,'unknown thought '+i);seen[i]+=1
 check(set(seen)==set(sources),'thought coverage');check(all(1<=n<=2 for n in seen.values()),'thought over2')
 for end in ['least','most']:
  g=d.get('segments',{}).get(end,{});check(2<=words(g.get('name',''))<=4,end+' name');check(1<=words(g.get('story',''))<=30,end+' story length')
 for key in ['whatTheySay','whatTheyThink','howTheyFeel','whatTheyDo','differences']:
  for x in d.get(key,[]):
   b=x if isinstance(x,str) else x['text']
   check(sum(words(z) for z in re.findall(r'\*\*([^*]+)\*\*',b))<=4,key+' over4 bold words: '+b)
 text=json.dumps(d,ensure_ascii=False)
 check(not re.search(r'(?<![A-Za-z0-9-])S[0-4](?![A-Za-z0-9-])',text),'scenario code in prose')
 print(sc, 'PASS structure/literal only' if not errors else errors, 'memberships',sum(seen.values()))
 if errors:sys.exit(1)

